        return arr[start]
    if end - start == 1:
        return max(arr[start], arr[end])
    mid = (start + end) // 2
    if arr[mid] > arr[mid + 1]:
        return arr[mid]
    if arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    if arr[start] > arr[mid]:
