def heapify(heap):
    n = len(heap)
    for i in range(n//2-1, -1, -1):
        heapify_down(heap, i, n)

def heapify_down(heap, i, n):
    smallest = i
    left = 2*i + 1
    right = 2*i + 2
    if left < n and heap[left] < heap[smallest]:
        smallest = left
    if right < n and heap[right] < heap[smallest]:
        smallest = right
    if smallest != i:
        heap[i], heap[smallest] = heap[smallest], heap[i]
